import{_ as a,o as e,c as o,a3 as t}from"./chunks/framework.DdpBa4_E.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/how-to-not-die-alone/09-第六章了解你的依恋类型.md","filePath":"books/how-to-not-die-alone/09-第六章了解你的依恋类型.md","lastUpdated":1794298621000}'),r={name:"books/how-to-not-die-alone/09-第六章了解你的依恋类型.md"};function i(l,p,n,s,h,d){return e(),o("div",null,[...p[0]||(p[0]=[t('<h2 id="第六章" tabindex="-1">第六章 <a class="header-anchor" href="#第六章" aria-label="Permalink to &quot;第六章&quot;">​</a></h2><p>了解你的依恋类型</p><h3 id="如何管理你的依恋类型" tabindex="-1">如何管理你的依恋类型 <a class="header-anchor" href="#如何管理你的依恋类型" aria-label="Permalink to &quot;如何管理你的依恋类型&quot;">​</a></h3><p>我是在芭蕾健身课上遇到薇薇安的。她总是第一个到，甚至在上课前就充满热情地做着提臀和微蹲这些动作。我也喜欢早一点来健身房，主要是为了缓和焦虑的情绪，生怕自己找不到好位置。我们每周都能见到对方。很明显，当我们的老师迟到时，我们俩都努力装出并不生气的样子。</p><p>有一天早晨，我们开始聊天，结果发现我们有很多共同之处。我们在东海岸有几个共同的好友。我们在同一年搬到了旧金山，还喜欢附近同一家咖啡馆。我们开始在下课后一起去那里喝咖啡。</p><p>在咖啡馆里，她向我坦白道：“所有我喜欢的男人都不喜欢我，但是所有喜欢我的男人，我都觉得他们很乏味。”在我们排队等着点咖啡的时候，她扫视了一圈，低声问我：“我该怎么办？我该将就吗？”</p><p>薇薇安不认为自己是一个能够降低标准的人。她在一家大公司的公关部门工作，负责所谓的“危机公关”。那一年以及之前的几年，危机没完没了；她随时都要保持战斗状态，应付各种法律诉讼或者网上的负面舆论。她每周健身五次，严格保持吃素食的习惯，而且刚刚获得了航海执照。这个女人掌控着一切，只有感情生活除外。</p><p>薇薇安知道我是一位婚恋匹配指导师。我们以前闲谈时，她提过几句自己的感情生活，但这次是她第一次真正敞开心扉。</p><p>“好吧，让我们从这个问题上后退一步，你以前的恋爱经历是怎么样的？”我问道。</p><p>“令人失望，”她说，“我和一个人谈了两年，我甚至都不知道我们是不是在谈恋爱。他肯定认为不是。在纽约的时候，他和我住同一栋公寓楼；只要他愿意，我们就会在一起。然后就是现在这一位，是我刚搬过来的时候，在工作中认识的。他传达的信息含混不清，最后不了了之。最近，我一直在用交友软件，我似乎已经约会过100万次了，但只要有人说喜欢我，我立刻就会失去兴趣。你说，我到底是怎么了？我是受到诅咒了吗？我会孤独终老吗？”</p><p>我笑了：“不，你没问题。你又漂亮又有趣，还知道怎么开船。我只是觉得你可能找错了人。”我试着靠着垫子保持不动，但感觉自己慢慢进入了心理辅导模式。我想帮助她。</p><p>“找错了人？我没说过非要找个高富帅呀。”</p><p>“我不是这个意思，”我打断她说，“你听说过依恋理论吗？”</p><h3 id="依恋理论基础概论" tabindex="-1">依恋理论基础概论 <a class="header-anchor" href="#依恋理论基础概论" aria-label="Permalink to &quot;依恋理论基础概论&quot;">​</a></h3><p>在我对客户解释的人际关系科学理论中，影响最大的就是依恋理论。这是一个常用的分析框架，可以解释我们为什么会被某些类型的人吸引，我们过去的感情关系为什么没有成功，以及我们为什么会被某些坏习惯困扰。</p><p>这类书籍建议你全面地读一读，比如，阿米尔·莱文和雷切尔·海勒合著的《读懂恋人心》（Attached），以及苏·约翰逊所著的《依恋与亲密关系》（Hold Me Tight）。不过，依恋理论的确对我的朋友、客户以及我自己的生活都产生了巨大的影响，所以我想在这本书中也介绍一下它的内容。我的一些客户在感情生活中挣扎了很多年。他们学习了这套理论的框架，利用它彻底改变了自己的行为方式。这并不容易，但很有效果。我认识不少人，把他们成功的婚姻归功于依恋理论告诉他们的事。（显然，我非常“依恋”依恋理论。）</p><p>点好饮料后，我和薇薇安坐在咖啡馆尽头一个满是垫子的角落里。我开始解释什么是依恋理论以及它为什么那么重要。</p><p>这一切都要追溯到英国发展心理学家约翰·鲍比的研究。他相信，孩子对母亲有一种固有的依恋。后来，美国心理学家玛丽·爱因斯沃斯进行了一项如今非常有名的实验：“陌生情境测验”，旨在研究儿童的不同依恋类型。她把母亲和婴儿（12～18个月大）请到她的实验室，在一系列不同的情景中观察他们。</p><p>首先，母亲和婴儿进入一间都是玩具的房间。因为母亲是安全堡垒（指如果需要，就能提供帮助的人），所以婴儿在房间里面玩耍和探索感到很安全。然后，实验助理指示母亲离开房间，并观察婴儿在母亲离开房间以及几分钟后回来时的反应。这个实验考察了婴儿在暂时失去安全堡垒的情况下，是否相信自己的需求会得到满足。</p><p>一些婴儿在母亲离开后，马上就表现出悲痛的样子。当母亲回来时，这些孩子会暂时得到安慰，停止哭泣，但随后会愤怒地推开母亲，再次开始哭泣。爱因斯沃斯称这些是“焦虑型依恋”的婴儿。</p><p>还有一些婴儿在母亲离开时开始哭泣，但母亲一回来就停止了，很快又开始玩玩具了。这些是“安全型依恋”的婴儿。</p><p>第三种婴儿对母亲离开房间没有反应，母亲回来时，他们也没有表示。他们假装没有受到这种情形的困扰。但是研究人员从这些婴儿的心率和血压水平的提高中可以看出，他们和那些哭泣的婴儿一样不安。这些是“回避型依恋”的婴儿。</p><p>爱因斯沃斯和她的团队得出结论，对于依恋和关注，我们每个人都有同样的需求，但我们会根据照顾自己的人的不同，发展出不同的应对策略。</p><p>过了一些年，研究人员发现，同样的理论也适用于成年人——我们被什么样的人吸引，我们和他们的关系如何，我们为什么在很多人际关系上成功或者失败，也和我们的依恋类型有关。但是，先不要因为你的感情生活不如意就责怪你妈妈，因为在决定成年人的依恋类型时，我们和父母的关系只是众多因素之一。</p><p>“那我是哪种类型？”薇薇安问。</p><p>“这个嘛，”我说，“那些焦虑型依恋的婴儿在母亲离开房间的时候哭泣，在母亲回来时继续哭。婴儿担心自己的需求得不到满足，因此要发泄愤怒和沮丧；成年人害怕被抛弃，希望一直和他们的伴侣保持联系。”</p><p>“这就是我。”</p><p>我看着薇薇安，笑了。因为我上周没来上课的时候，她连珠炮似的给我发了7条短信。</p><p>焦虑型依恋的人，他们的大脑中充满“激活策略”，迫使他们忙不迭地重新恢复亲密感。例如，他们可能会一刻不停地想着自己的伴侣，或者，会一直想着伴侣的优点而看轻了自己的优点。这种扭曲导致了恐慌。如果没有立即得到伴侣的回复，他们就担心自己是不是被抛弃了。只有当他们一刻不停地与伴侣联系时，才能摆脱焦虑。这也导致他们会一头扎进某一段感情中，并在这段感情逝去后，依然不肯放手。因为他们害怕孤独，担心这是他们唯一得到爱情的机会。</p><p>我说：“我不是在指责什么，焦虑型依恋的人通常会有“‘抗议行为’。”</p><p>焦虑型依恋的人的行为通常是为了吸引伴侣的注意。他们可能会过于频繁地打电话或者发短信；或者以离开为威胁，意图引起对方妒忌；或者通过挂断电话、不接电话来引起对方关注。</p><p>那些回避型依恋的婴儿，即使感到同样的不安，但在母亲回到房间时表现得漠不关心。他们觉得不能依赖照顾他们的人，因为这些人只能满足他们的部分需求。他们长大后会变成回避型依恋的成年人：他们装作不想和别人发生联系，尽可能减少被拒绝后的痛苦。他们不相信可以依靠别人来满足他们在感情上的需求，所以他们总是避免与任何人走得太近。当关系越来越亲密时，他们就试图离开。这些离开的尝试叫作“去激活策略”。如果你听到有人说，“我还没有准备好和你明确关系”，或者“我只是需要一些空间”，或者“我的工作太忙了，所以我现在还不想深入”，那么你就是遇到了回避型依恋的行为了。</p><p>这种依恋类型的人往往会仔细琢磨伴侣不如人意的地方，并以此为借口离开，重获自由。他们幻想着如果单身了或者和另外的人在一起会更快乐。</p><p>当我描述回避型依恋时，薇薇安点了点头，说：“这听起来跟我以前约会过的每一个人都一样。”</p><p>“别对自己太苛刻了。”我对她说。这种恋爱模式其实非常普遍，被称为“焦虑-回避循环”。焦虑型依恋的人预料到他们的伴侣试图离开，所以反过来追得更紧。这是薇薇安与住同一栋公寓楼的前男友之间发生的事。</p><p>“就是这样，”薇薇安说，“我以前总想知道：他会给我回电话吗？我这个周末能见他吗？”被拒绝的可能性造成了焦虑，薇薇安对这种意乱情迷的滋味感到迷惑不解。当对方真的开始疏远时，她的感觉就更强烈了。</p><p>与此同时，回避型依恋的男人可能正在经历着完全不同的事情。这种依恋类型的人害怕失去独立。所以，当薇薇安开始拉近和他的距离时，很可能会强化他对亲密关系的扭曲看法，反而让他想逃得更远。</p><p>“如果你用这种方式思考，”我说，“焦虑-回避循环可以解释你碰到的事情。回避型依恋的人非常善于拒绝、疏远别人；直到对方特别执着的时候，他们就会结束这段关系。”</p><p>“如果我不执着，那就不是我了。”薇薇安说。</p><p>服务员终于端来了我们的饮料。薇薇安向窗外望去，注视着咖啡馆外的长椅上坐在一起的一对夫妇。“那最后一类婴儿呢？当他们的母亲回来时会停止哭泣的婴儿呢？”她问道。</p><p>“那些叫作安全型依恋的婴儿，他们相信自己的母亲会满足他们的需求。安全依恋型的人是理想的伴侣。他们稳重可靠、值得信赖。他们会避免戏剧化的激烈场面，如果避免不了，在戏剧化场面到来时，也会设法缓和它。他们随和、宽容、善于沟通。他们表里如一，为亲密关系创造出健康的边界。他们很享受亲密关系。与回避型和焦虑型的人相比，和安全型依恋的人在一起更容易获得美满的亲密关系。”</p><p>“我压根儿没有和这样的人约会过，”薇薇安答道，“安全型依恋的人有多少呢？难道只占总人口的1%？”</p><p>事实上，有50%的人是安全型依恋，20%的人是焦虑型依恋，25%的人是回避型依恋，而后两类人往往纠结在一起，陷入焦虑-回避循环。这看起来似乎是个好消息。问题是，虽然安全型依恋的人占总人口的50%，但在单身人口中所占的比例要小得多，因为安全型依恋的人往往很快就被抢光了。他们善于建立健康的亲密关系，所以他们很快就会留在这段关系里。因此，在婚姻市场上见得更多的都是焦虑型以及回避型的恋爱者。</p><p>听我解释完这一切，薇薇安叹了口气，说：“我放弃了。”说完，她一口气喝干了最后一点奶昔。</p><p>尽管嘴上这么说，但她没有这么做。</p><h4 id="exercises" tabindex="-1">exercises <a class="header-anchor" href="#exercises" aria-label="Permalink to &quot;exercises&quot;">​</a></h4><p>练习</p><p>确定你的依恋类型</p><p>如果你对自己的依恋类型感到好奇，试试回答以下的问题：</p><p>1.对于亲密关系和亲昵行为，你感到自在吗？你在多大程度上会避免亲密关系？</p><p>2.伴侣对你的爱意和兴趣让你感到焦虑吗？你是否经常担心你们之间的感情关系？</p><p>如果你渴望亲密关系，但你对这段感情的未来，对伴侣对你的兴趣程度缺乏安全感，那你可能就是焦虑型依恋的人。当你们的关系太过亲密的时候，如果你感到不舒服，认为自己更重视自由而不是亲密关系，你可能就是回避型依恋的人。如果你对彼此亲密感到自在，对一个人独处也感到自在，而且并不怎么担心你们的感情，那你就是安全型依恋的人。</p><p>你可以在我的网站loganury.com上做在线测试，确认你的依恋类型。</p><h3 id="寻找安全型伴侣" tabindex="-1">寻找安全型伴侣 <a class="header-anchor" href="#寻找安全型伴侣" aria-label="Permalink to &quot;寻找安全型伴侣&quot;">​</a></h3><p>尽管薇薇安说要放弃，但在我们谈话后的几个月里，她还是在努力尝试改变约会方式，她开始寻找安全型依恋的人。这需要时间。她和新结识的人出去约会，然后抱怨他们乏味。当我深入询问时，我发现这通常意味着这个人对她很好。比如，她告诉一位已经和她约会过两次的男士，她下个周末要去西雅图出差，对方给她发来一张清单，上面是推荐的餐馆。她向我讲述完这件事，说：“这就是我再也不想见他的原因。”</p><p>“等等，你说什么？”我说。</p><p>“他显然太喜欢我了，真够可悲的。”</p><p>我尽最大努力帮助她换个角度看问题。这个人喜欢她，只是想帮她的忙。这是一种安全型行为，不是什么可悲的行为。我们开始一起努力，帮她打破焦虑-回避循环。</p><p>如果你的故事与薇薇安的类似，并且相信自己同样是焦虑型依恋的人，那这也是你的家庭作业。当然，我并不是说每个你觉得乏味的人其实都是安全型依恋的人。他们可能真的很乏味。但现在是时候停下脚步了，别再玩追逐游戏了。这就是我对薇薇安提出的挑战：试着和安全型的伴侣约会——那些说给你发短信就会给你发短信的人；那些让你知道他们在想什么的人；那些不跟你玩游戏，避免戏剧性场面或者在戏剧性场面发生后，会尝试降低它影响的人。</p><p>对于回避型依恋的读者也是一样，你们也要找到一个安全型依恋的伴侣。</p><h3 id="学会自我调节" tabindex="-1">学会自我调节 <a class="header-anchor" href="#学会自我调节" aria-label="Permalink to &quot;学会自我调节&quot;">​</a></h3><p>与此同时，你可以努力让自己变成安全型依恋的人。人这一生的依恋类型相对固定，不过，大约有1/4的人可以在四年多的时间里改变他们的依恋类型。这需要努力，但你的确可以改变自己的依恋类型。</p><p>薇薇安决心做出改变，这对她来说意味着去学习如何自我调节——管理破坏性的冲动和情绪。她训练自己在没有立即收到回复时不要惊慌。遇到这种时候，她要么出去散步，要么给朋友打电话来缓解自己的焦虑（这两种方式都比给前一天在办公室的电梯里遇到的男人发14条短信更健康）。</p><p>对于那些回避型依恋的人，当你感觉自己想要疏远时，注意你的感受。学会向对方要求空间，和对方加强联系，而不是消失在自己的空间里。或者，当你发现自己正盯着伴侣的缺点不放，想借此分手时，尝试一种不同的方法：训练自己去寻找对方积极的品质。牢记一点：人无完人，如果你离开了，你遇到的下一个人也会是不完美的。</p><p>主动去改变自身固有的依恋类型这件事很有挑战性。我们之所以成为现在的样子，有很多是潜意识里的原因造成的，挖掘过去可能会带来意想不到的结果。我们和母亲的关系对我们的依恋类型有什么影响？如果我们现在找到了更健康的依恋类型，是否意味着我们背叛或者抛弃了她？你可能不得不面对一件事，就是你没有从你最需要的人那里得到你需要的东西。许多人发现和心理治疗师讨论这些问题很有帮助。</p><p>每次芭蕾健身课结束后，我都和薇薇安继续讨论她的感情生活。很快，当男人们开始对她感兴趣时，她不再说他们“乏味”了。她骄傲地给我发短信，告诉我她拒绝了一个追求者，因为他明显是回避型依恋的人。你猜怎么着？大约六个月后，她遇到了一个英俊的小伙子，他刚从休斯敦搬到旧金山。他们初次约会后，一个周五的晚上，他打电话给她说：“我真的很喜欢你，我想明天再见到你。”她不再觉得他“可悲”了。第二天，她接受他的邀请，和他一起外出吃了早餐。早餐变成了散步，散步又变成了和她的朋友们在一家啤酒厂见面。啤酒厂见面又变成了喝醉了坐出租车回到他家。两年后，他们仍然在一起。</p><p>总结</p><ol><li><p>依恋理论是理解亲密关系的一个常用框架。它可以解释为什么你会被某些人吸引，为什么过去的亲密关系没有成功，为什么你会陷入某种糟糕的习惯模式中。</p></li><li><p>如果你渴望亲密关系，但你对这段感情的未来、对伴侣对你的感兴趣程度缺乏安全感，那你可能就是焦虑型依恋的人。如果你对亲密关系感到不舒服，更看重独立而不是彼此的关系，你可能是回避型依恋的人。如果你对彼此亲密感到自在，对一个人独处也感到自在，而且清楚独处和亲密的界限，那你可能是安全型依恋的人。</p></li><li><p>安全型依恋的人占总人口的50%，但在婚恋市场上比例不高，因为他们较容易建立一段亲密关系并维持下去。焦虑型依恋和回避型依恋的人经常和对方约会，更加强化了他们的负面倾向。</p></li><li><p>如果你是焦虑型依恋或者回避型依恋的人，你可以通过寻找一个安全型的伴侣，学习自我调节——管理破坏性的冲动和情绪——来帮助自己掌握维持亲密关系的技巧。</p></li></ol>',68)])])}const u=a(r,[["render",i]]);export{c as __pageData,u as default};
